-- PostgreSQL Database Schema for Tasks Project
-- Generated by Entity Framework Core Migration: InitialCreate
-- Database: tasks_project_db

-- ============================================
-- CREATE TABLES
-- ============================================

-- Users Table
CREATE TABLE IF NOT EXISTS "Users" (
"Id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "First_name" character varying(100) NOT NULL,
    "Last_name" character varying(100) NOT NULL,
    "Email" character varying(255) NOT NULL,
    "Password" character varying(255) NOT NULL,
    "Wont_help" boolean NOT NULL
);

-- Categories Table (with self-referencing parent-child relationship)
CREATE TABLE IF NOT EXISTS "Categories" (
    "Id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Color" character varying(50) NOT NULL,
    "father_id" integer REFERENCES "Categories"("Id") ON DELETE RESTRICT
);

-- ChatSessions Table
CREATE TABLE IF NOT EXISTS "ChatSessions" (
    "Id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL REFERENCES "Users"("Id") ON DELETE CASCADE,
    "Title" character varying(255) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL
);

-- Tasks Table
CREATE TABLE IF NOT EXISTS "Tasks" (
    "Id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "Title" character varying(200) NOT NULL,
    "Task_Date" timestamp with time zone NOT NULL,
    "user_id" integer NOT NULL REFERENCES "Users"("Id") ON DELETE CASCADE,
    "File_path" character varying(500) NOT NULL,
    "CategoryId" integer NOT NULL REFERENCES "Categories"("Id") ON DELETE CASCADE
);

-- Messages Table
CREATE TABLE IF NOT EXISTS "Messages" (
    "Id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "SessionId" integer NOT NULL REFERENCES "ChatSessions"("Id") ON DELETE CASCADE,
    "Role" character varying(50) NOT NULL,
    "Content" text NOT NULL,
  "CreatedAt" timestamp with time zone NOT NULL
);

-- FavoriteUserCategories Table (Junction table for Many-to-Many)
CREATE TABLE IF NOT EXISTS "FavoriteUserCategories" (
    "Id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "user_id" integer NOT NULL REFERENCES "Users"("Id") ON DELETE CASCADE,
    "category_id" integer NOT NULL REFERENCES "Categories"("Id") ON DELETE CASCADE,
  UNIQUE("user_id", "category_id")
);

-- ============================================
-- CREATE INDEXES
-- ============================================

CREATE INDEX IF NOT EXISTS "IX_Categories_father_id" ON "Categories"("father_id");
CREATE INDEX IF NOT EXISTS "IX_ChatSessions_UserId" ON "ChatSessions"("UserId");
CREATE INDEX IF NOT EXISTS "IX_FavoriteUserCategories_category_id" ON "FavoriteUserCategories"("category_id");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_FavoriteUserCategories_user_id_category_id" ON "FavoriteUserCategories"("user_id", "category_id");
CREATE INDEX IF NOT EXISTS "IX_Messages_SessionId" ON "Messages"("SessionId");
CREATE INDEX IF NOT EXISTS "IX_Tasks_CategoryId" ON "Tasks"("CategoryId");
CREATE INDEX IF NOT EXISTS "IX_Tasks_user_id" ON "Tasks"("user_id");

