/*
ONE-TO-MANY RELATIONSHIPS:
1. Users (1) → (Many) Tasks
   - Foreign Key: Tasks.user_id → Users.Id
   - Cascade Delete: ON DELETE CASCADE

2. Users (1) → (Many) ChatSessions
   - Foreign Key: ChatSessions.UserId → Users.Id
   - Cascade Delete: ON DELETE CASCADE

3. Users (1) → (Many) FavoriteUserCategories
   - Foreign Key: FavoriteUserCategories.user_id → Users.Id
   - Cascade Delete: ON DELETE CASCADE

4. Categories (1) → (Many) Tasks
   - Foreign Key: Tasks.CategoryId → Categories.Id
   - Cascade Delete: ON DELETE CASCADE

5. Categories (1) → (Many) FavoriteUserCategories
   - Foreign Key: FavoriteUserCategories.category_id → Categories.Id
   - Cascade Delete: ON DELETE CASCADE

6. ChatSessions (1) → (Many) Messages
   - Foreign Key: Messages.SessionId → ChatSessions.Id
   - Cascade Delete: ON DELETE CASCADE

SELF-REFERENCING RELATIONSHIP:
7. Categories (Parent) → Categories (Child)
   - Foreign Key: Categories.father_id → Categories.Id
   - Restrict Delete: ON DELETE RESTRICT (prevents deletion if children exist)

MANY-TO-MANY RELATIONSHIP (via Junction Table):
8. Users ↔ FavoriteUserCategories ↔ Categories
   - Unique Constraint: UNIQUE(user_id, category_id) prevents duplicate favorites
*/

-- ============================================
-- SAMPLE QUERIES
-- ============================================

-- Get all tasks for a user
SELECT t.* FROM "Tasks" t
WHERE t."user_id" = 1;

-- Get all favorite categories for a user
SELECT c.* FROM "Categories" c
INNER JOIN "FavoriteUserCategories" fuc ON c."Id" = fuc."category_id"
WHERE fuc."user_id" = 1;

-- Get all messages in a chat session
SELECT m.* FROM "Messages" m
WHERE m."SessionId" = 1
ORDER BY m."CreatedAt" DESC;

-- Get all child categories of a parent category
SELECT * FROM "Categories"
WHERE "father_id" = 1;

-- Get all tasks for a specific category
SELECT t.* FROM "Tasks" t
WHERE t."CategoryId" = 1;

-- Get user with all their tasks and chat sessions
SELECT u.*, 
       COUNT(DISTINCT t."Id") as task_count,
       COUNT(DISTINCT cs."Id") as chat_count
FROM "Users" u
LEFT JOIN "Tasks" t ON u."Id" = t."user_id"
LEFT JOIN "ChatSessions" cs ON u."Id" = cs."UserId"
WHERE u."Id" = 1
GROUP BY u."Id";

